const h=(v)=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmt=(v)=>{if(!v)return '-';try{return new Intl.DateTimeFormat('th-TH',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Bangkok'}).format(new Date(v))}catch{return h(v)}};
const errText=(e)=>e?.message||e?.error_description||e?.details||String(e||'เกิดข้อผิดพลาด');
const rpc=async(name,args={})=>{const{data,error}=await sb.rpc(name,args);if(error)throw error;return data};
const query=async(table,select='*')=>{const{data,error}=await sb.from(table).select(select);if(error)throw error;return data||[]};
function route(){return (location.hash.replace(/^#\/?/,'').split('?')[0]||'dashboard').toLowerCase()}
function go(r){location.hash='#/'+r}
function showError(message){const el=document.getElementById('page-error');if(el){el.innerHTML=`<div class="error-panel"><b>ทำรายการไม่สำเร็จ</b><div>${h(message)}</div></div>`}else alert(message)}
function busy(text='กำลังโหลด...'){return `<div class="empty">${h(text)}</div>`}
function modal(title,body){document.body.insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modal-bg"><div class="modal"><div class="section-head"><h3>${h(title)}</h3><button class="btn" id="modal-close">ปิด</button></div>${body}</div></div>`);document.getElementById('modal-close').onclick=closeModal;document.getElementById('modal-bg').addEventListener('mousedown',e=>{if(e.target===e.currentTarget)closeModal()})}
function closeModal(){document.getElementById('modal-bg')?.remove()}
function downloadCsv(rows,name){const text=rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
async function cleanupLegacy(){try{if('serviceWorker'in navigator){const rs=await navigator.serviceWorker.getRegistrations();await Promise.all(rs.map(r=>r.unregister()))}if('caches'in window){const names=await caches.keys();await Promise.all(names.map(n=>caches.delete(n)))}}catch{}}
void cleanupLegacy();

