 teacher:[['dashboard','ภาพรวม'],['attendance','เช็กชื่อ'],['teaching','การสอน'],['worksheets','ใบงาน'],['exams','ข้อสอบ'],['grading','ตรวจงาน'],['reports','คะแนน/รายงาน'],['profile','โปรไฟล์']],
 user:[['dashboard','หน้าหลัก'],['my-worksheets','ใบงานของฉัน'],['my-exams','ข้อสอบของฉัน'],['profile','โปรไฟล์']]
