 root.innerHTML=`<div class="login-page"><section class="login-hero"><div class="hero-badge">NR</div><h1>DOC-FULL-NR</h1><h2>ระบบใบงานและการจัดการชั้นเรียน</h2><p>Production Console รุ่นใหม่สำหรับ Desktop / Tablet ตัด Mobile Runtime และ UI รุ่นเดิมออกจากการใช้งานจริง</p><div class="hero-points"><span>✓ Attendance</span><span>✓ Worksheets</span><span>✓ Exams</span><span>✓ Gradebook</span><span>✓ Room Groups</span></div></section><section class="login-panel"><div class="login-card"><div class="eyebrow">PRODUCTION LOGIN</div><h2>เข้าสู่ระบบ</h2><p class="muted">ใช้บัญชีเดิมของ DOC-FULL-NR</p><div id="login-error">${message?`<div class="error-panel">${h(message)}</div>`:''}</div><form id="login-form"><label>อีเมล / รหัสนักศึกษา / Username<input name="email" type="text" autocomplete="username" required></label><label>รหัสผ่าน<input name="password" type="password" autocomplete="current-password" minlength="8" required></label><button class="btn primary wide" id="login-btn">เข้าสู่ระบบ</button></form><div class="login-foot">V23 Desktop/Tablet Production Recovery</div></div></section></div>`;
 document.getElementById('login-form').onsubmit=async e=>{e.preventDefault();const b=document.getElementById('login-btn');b.disabled=true;b.textContent='กำลังเข้าสู่ระบบ...';const f=new FormData(e.currentTarget);const raw=String(f.get('email')||'').trim();const email=raw.includes('@')?raw:`${raw.toLowerCase()}@docfullnr.local`;const{error}=await sb.auth.signInWithPassword({email,password:String(f.get('password')||'')});if(error){document.getElementById('login-error').innerHTML=`<div class="error-panel">${h(error.message)}</div>`;b.disabled=false;b.textContent='เข้าสู่ระบบ'}};
