function renderShell(){
 const r=route(),role=state.profile?.role||'user',nav=NAV[role]||NAV.user;
 root.innerHTML=`<div class="shell"><header class="app-header"><div class="identity"><div class="logo-mark">NR</div><div><strong>DOC-FULL-NR</strong><small>Production Console • V23 Desktop/Tablet</small></div></div><div class="account"><div><b>${h(state.profile?.full_name||state.profile?.username||'ผู้ใช้')}</b><small>${h(role.toUpperCase())}</small></div><button class="btn ghost" id="logout-btn">ออกจากระบบ</button></div></header><nav class="topnav">${nav.map(([id,label])=>`<button data-route="${id}" class="${r===id?'active':''}">${h(label)}</button>`).join('')}</nav><main class="workspace"><div id="page-error"></div><div id="view">${busy()}</div></main></div>`;
 document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>go(b.dataset.route));
 document.getElementById('logout-btn').onclick=()=>sb.auth.signOut();
}

async function loadProfile(){
 if(!state.session){state.profile=null;return}
 const{data,error}=await sb.from('profiles').select('*').eq('id',state.session.user.id).maybeSingle();
 if(error)throw error;if(!data)throw new Error('ไม่พบโปรไฟล์ผู้ใช้');state.profile=data;
}

async function render(){
 if(!state.authReady)return;
 if(!state.session){renderLogin();return}
 if(!state.profile){try{await loadProfile()}catch(e){renderLogin(errText(e));return}}
 const r=route();const staffOnly=['attendance','teaching','worksheets','exams','grading','reports'];const adminOnly=['users','classrooms','room-groups','subjects'];
 if(staffOnly.includes(r)&&!isStaff()){go('dashboard');return}if(adminOnly.includes(r)&&!isAdmin()){go('dashboard');return}
 renderShell();
 try{
  if(r==='dashboard')await pageDashboard();
  else if(r==='attendance')await pageAttendance();
  else if(r==='teaching')await pageTeaching();
  else if(r==='worksheets')await pageWorksheets();
  else if(r==='exams')await pageExams();
  else if(r==='grading')await pageGrading();
  else if(r==='reports')await pageReports();
  else if(r==='users')await pageUsers();
  else if(r==='classrooms')await pageClassrooms();
  else if(r==='room-groups')await pageRoomGroups();
  else if(r==='subjects')await pageSubjects();
  else if(r==='my-worksheets')await pageMyWorksheets();
  else if(r==='my-exams')await pageMyExams();
  else if(r==='profile')await pageProfile();
  else{document.getElementById('view').innerHTML='<div class="panel"><h2>ไม่พบหน้า</h2></div>'}
 }catch(e){document.getElementById('view').innerHTML='';showError(errText(e));console.error(e)}
}

