 document.querySelectorAll('[data-status]').forEach(b=>b.onclick=async()=>{try{await rpc('staff_set_attendance_status_v206',{p_session_id:id,p_user_id:b.dataset.user,p_status:b.dataset.status,p_note:'ปรับจาก V23 Desktop Console'});closeModal();await openRoster(id,s)}catch(e){showError(errText(e))}})
