async function pageRoomGroups(){
 const v=document.getElementById('view');const [groups,users,subs]=await Promise.all([rpc('admin_room_groups_v206'),query('profiles','id,full_name,username,student_code,class_name,role,active'),query('subjects','id,code,name,active,subject_type')]);const students=users.filter(u=>u.role==='user'&&u.active),subjects=subs.filter(s=>s.active&&s.subject_type==='subject');
 v.innerHTML=`<div class="page-head"><div><div class="eyebrow">ROOM GROUPS</div><h1>กลุ่มห้อง</h1><p>จัดสมาชิก ผูกรายวิชา และ Sync เข้าห้องเรียนจริง</p></div><button class="btn primary" id="new-group">+ สร้างกลุ่มห้อง</button></div><div class="card-grid">${(groups||[]).map(g=>`<article class="panel"><div class="row-between"><span class="code-pill">${h(g.code)}</span><span class="status-chip ok">ACTIVE</span></div><h3>${h(g.name)}</h3><p>${h(g.classroom_name||'ยังไม่ sync ห้องเรียน')}</p><div class="mini-stats"><span>สมาชิก <b>${g.member_count||0}</b></span><span>วิชา <b>${g.bound_subject_count||0}</b></span></div><button class="btn" data-group="${g.id}">จัดการกลุ่ม</button></article>`).join('')}</div>`;
 document.getElementById('new-group').onclick=()=>openGroupEditor(null,students,subjects);v.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>openGroupEditor((groups||[]).find(g=>g.id===b.dataset.group),students,subjects));
}
async function openGroupEditor(g,students,subjects){
 let selected=[];if(g){selected=(await rpc('admin_room_group_members_v205',{p_group_id:g.id})||[]).filter(x=>x.active).map(x=>x.user_id)}
 modal(g?'จัดการกลุ่มห้อง':'สร้างกลุ่มห้อง',`<form id="group-form"><div class="form-grid"><label>รหัสกลุ่ม<input name="code" value="${h(g?.code||'')}"></label><label>ชื่อกลุ่ม<input name="name" value="${h(g?.name||'')}" required></label><label>ปีการศึกษา<input name="year" value="${h(g?.academic_year||'2569')}"></label><label>ภาคเรียน<input name="semester" value="${h(g?.semester||'1')}"></label><label>ระดับ<input name="level" value="${h(g?.level||'')}"></label><label>สาขา<input name="major" value="${h(g?.major||'')}"></label><label class="span2">ผูกรายวิชา<select name="subject"><option value="">ยังไม่ผูกเพิ่ม</option>${subjects.map(s=>`<option value="${s.id}">${h(s.code)} ${h(s.name)}</option>`).join('')}</select></label></div><div class="member-picker"><h4>สมาชิก</h4><div class="member-grid">${students.map(u=>`<label class="check-card"><input type="checkbox" name="members" value="${u.id}" ${selected.includes(u.id)?'checked':''}><span><b>${h(u.full_name||u.username||'-')}</b><small>${h(u.student_code||'-')} • ${h(u.class_name||'-')}</small></span></label>`).join('')}</div></div><div class="modal-actions"><button type="button" class="btn" id="group-cancel">ยกเลิก</button><button class="btn primary">บันทึก + Sync</button></div></form>`);document.getElementById('group-cancel').onclick=closeModal;document.getElementById('group-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const r=await rpc('admin_upsert_room_group_v205',{p_group_id:g?.id||null,p_code:String(f.get('code')||''),p_name:String(f.get('name')||''),p_academic_year:String(f.get('year')||''),p_semester:String(f.get('semester')||''),p_level:String(f.get('level')||''),p_department:'',p_major:String(f.get('major')||''),p_description:'',p_active:true});const gid=g?.id||r.id;const ids=f.getAll('members').map(String);await rpc('admin_replace_room_group_members_v206',{p_group_id:gid,p_members:ids.map((id,i)=>({user_id:id,seat_number:i+1}))});if(f.get('subject'))await rpc('admin_bind_room_group_subject_v206',{p_group_id:gid,p_subject_id:f.get('subject'),p_active:true});await rpc('admin_auto_number_room_group_v206',{p_group_id:gid});await rpc('admin_sync_room_group_v206',{p_group_id:gid});closeModal();await pageRoomGroups()}catch(er){showError(errText(er))}};
}

async function pageMyWorksheets(){
 const v=document.getElementById('view');const{data,error}=await sb.from('worksheets').select('id,title,due_at,mode,status,questions,subject_id,subjects(code,name)').eq('status','published').order('due_at',{ascending:true});if(error)throw error;v.innerHTML=`<div class="page-head"><div><div class="eyebrow">MY WORKSHEETS</div><h1>ใบงานของฉัน</h1><p>ใบงานที่เปิดให้ทำ</p></div></div><div class="card-grid">${(data||[]).map(w=>`<article class="panel"><span class="code-pill">${h(w.subjects?.code||'')}</span><h3>${h(w.title)}</h3><p>${h(w.subjects?.name||'')} • กำหนด ${fmt(w.due_at)}</p><button class="btn primary" data-student-work="${w.id}">${w.mode==='paper'?'พิมพ์ใบงาน':'เปิดใบงาน'}</button></article>`).join('')}</div>`;v.querySelectorAll('[data-student-work]').forEach(b=>b.onclick=()=>openStudentWork(b.dataset.studentWork));
}
async function openStudentWork(id){
 const [{data:w,error:e1},{data:sub,error:e2}]=await Promise.all([sb.from('worksheets').select('*,subjects(code,name)').eq('id',id).single(),sb.from('submissions').select('*').eq('worksheet_id',id).eq('user_id',state.session.user.id).maybeSingle()]);if(e1)throw e1;if(e2)throw e2;if(w.mode==='paper'){openPaper(w);return}const locked=sub&&['submitted','confirmed','graded'].includes(sub.status),answers=sub?.answers||{},qs=Array.isArray(w.questions)?w.questions:[];
 modal(w.title,`<p class="muted">${h(w.subjects?.code||'')} ${h(w.subjects?.name||'')} • กำหนด ${fmt(w.due_at)}</p><form id="student-work-form">${qs.map((q,i)=>`<div class="question"><b>${i+1}. ${h(q.text)}</b><small>${q.points||0} คะแนน</small>${q.type==='choice'?`<div>${(q.options||[]).map(o=>`<label class="choice"><input type="radio" name="q_${h(q.id)}" value="${h(o)}" ${answers[q.id]===o?'checked':''} ${locked?'disabled':''}>${h(o)}</label>`).join('')}</div>`:`<textarea name="q_${h(q.id)}" ${locked?'disabled':''}>${h(answers[q.id]||'')}</textarea>`}</div>`).join('')}<div class="modal-actions">${locked?`<span class="success-text">ส่งงานแล้ว ${fmt(sub.submitted_at)}</span>`:`<button type="button" class="btn" id="save-draft">บันทึกร่าง</button><button class="btn success">ส่งงาน</button>`}</div></form>`);if(locked)return;const collect=()=>{const f=new FormData(document.getElementById('student-work-form')),a={};for(const q of qs)a[q.id]=f.get(`q_${q.id}`)||'';return a};document.getElementById('save-draft').onclick=async()=>{try{await rpc('save_worksheet_draft',{p_worksheet_id:id,p_answers:collect(),p_attachment_paths:sub?.attachment_paths||[]});closeModal();alert('บันทึกร่างแล้ว')}catch(e){showError(errText(e))}};document.getElementById('student-work-form').onsubmit=async e=>{e.preventDefault();try{await rpc('finalize_digital_submission',{p_worksheet_id:id,p_answers:collect(),p_attachment_paths:sub?.attachment_paths||[]});closeModal();alert('ส่งงานเรียบร้อย')}catch(er){showError(errText(er))}};
}


async function pageMyExams(){
 const v=document.getElementById('view');
 const [{data:exams,error},statuses]=await Promise.all([
   sb.from('exams').select('id,title,description,exam_kind,status,open_at,due_at,duration_minutes,full_score,subjects(code,name)').in('status',['published','closed']).order('open_at',{ascending:false}),
   rpc('my_exam_status_v194',{})
 ]);
 if(error)throw error;const statusMap=new Map((statuses||[]).map(x=>[x.exam_id,x]));
 v.innerHTML=`<div class="page-head"><div><div class="eyebrow">MY EXAMS</div><h1>ข้อสอบของฉัน</h1><p>ข้อสอบที่ได้รับสิทธิ์และสถานะการสอบล่าสุด</p></div></div><div class="card-grid">${(exams||[]).map(e=>{const st=statusMap.get(e.id)||{};return `<article class="panel"><div class="row-between"><span class="code-pill">${h(e.subjects?.code||'')}</span><span class="status-chip ${st.can_start?'ok':''}">${h(st.display_status||e.status)}</span></div><h3>${h(e.title)}</h3><p>${h(e.subjects?.name||'')} • ${h(e.exam_kind||'')} • ${e.full_score??'-'} คะแนน</p><small>เปิด ${fmt(e.open_at)} • ปิด ${fmt(e.due_at)}</small><div style="margin-top:12px">${st.can_start?`<button class="btn primary" data-start-exam="${e.id}">${st.latest_attempt_status==='draft'?'ทำต่อ':'เริ่มสอบ'}</button>`:'<button class="btn" disabled>ยังเริ่มไม่ได้</button>'}</div></article>`}).join('')}</div>`;
 v.querySelectorAll('[data-start-exam]').forEach(b=>b.onclick=()=>openStudentExam(b.dataset.startExam));
}
async function openStudentExam(examId){
 const a=await rpc('start_exam_v194',{p_exam_id:examId});const exam=a.exam||{},qs=Array.isArray(exam.questions)?exam.questions:[],saved=a.answers||{};
 const optionText=o=>typeof o==='string'?o:(o?.text??o?.label??o?.value??JSON.stringify(o));
 modal(exam.title||'ทำข้อสอบ',`<div class="info-panel">เวลาสิ้นสุด ${fmt(a.expires_at)} • ครั้งที่ ${a.entitlement_attempt_no||a.attempt_no||1}</div><form id="student-exam-form">${qs.map((q,i)=>{const id=String(q.id??q.question_id??`q${i+1}`),title=q.prompt??q.text??q.question??`ข้อ ${i+1}`,opts=Array.isArray(q.options)?q.options:[];return `<div class="question"><b>${i+1}. ${h(title)}</b>${opts.length?`<div>${opts.map(o=>{const val=optionText(o);return `<label class="choice"><input type="radio" name="exam_${h(id)}" value="${h(val)}" ${saved[id]===val?'checked':''}>${h(val)}</label>`}).join('')}</div>`:`<textarea name="exam_${h(id)}">${h(saved[id]||'')}</textarea>`}</div>`}).join('')}<div class="modal-actions"><button type="button" class="btn" id="save-exam">บันทึกคำตอบ</button><button class="btn success">ส่งข้อสอบ</button></div></form>`);
 const collect=()=>{const f=new FormData(document.getElementById('student-exam-form')),ans={};qs.forEach((q,i)=>{const id=String(q.id??q.question_id??`q${i+1}`);ans[id]=f.get(`exam_${id}`)||''});return ans};
 document.getElementById('save-exam').onclick=async()=>{try{await rpc('save_exam_answers',{p_attempt_id:a.attempt_id,p_answers:collect()});alert('บันทึกคำตอบแล้ว')}catch(e){showError(errText(e))}};
 document.getElementById('student-exam-form').onsubmit=async e=>{e.preventDefault();if(!confirm('ยืนยันส่งข้อสอบ?'))return;try{const r=await rpc('submit_exam_attempt_v194',{p_attempt_id:a.attempt_id,p_answers:collect(),p_request_key:crypto.randomUUID()});closeModal();alert(r?.display_status||'ส่งข้อสอบแล้ว');await pageMyExams()}catch(er){showError(errText(er))}};
}

async function pageProfile(){
 const v=document.getElementById('view'),p=state.profile||{};const rows=[['ชื่อ-สกุล',p.full_name||'-'],['ชื่อที่แสดง',p.display_name||'-'],['ชื่อผู้ใช้',p.username||'-'],['สิทธิ์',p.role||'-'],['รหัสนักศึกษา',p.student_code||'-'],['ระดับ',p.grade_level||'-'],['ห้อง',p.class_name||[p.grade_level,p.room_label].filter(Boolean).join('')||'-'],['แผนก',p.department||'-'],['สาขา',p.major||'-'],['เลขที่',p.seat_number??'-'],['โทรศัพท์',p.phone||'-'],['สถานะบัญชี',p.approval_status||'-']];
 v.innerHTML=`<div class="page-head"><div><div class="eyebrow">MY ACCOUNT</div><h1>โปรไฟล์</h1><p>ข้อมูลบัญชีจากฐานข้อมูลจริง • หน้านี้เป็นแบบอ่านอย่างเดียวเพื่อไม่ชนสิทธิ์ RLS</p></div></div><div class="panel" style="max-width:900px"><div class="kv-grid">${rows.map(([k,val])=>`<div class="kv"><small>${h(k)}</small><b>${h(val)}</b></div>`).join('')}</div></div>`;
}
window.addEventListener('hashchange',()=>void render());
const {data:{session}}=await sb.auth.getSession();state.session=session;try{if(session)await loadProfile()}catch(e){console.error(e)}state.authReady=true;await render();
